For me in the keychain I got the Claude access and refresh token and added it to `~/.local/share/opencode/auth.json`. And got it working again. 

```
{
  "anthropic": {
    "type": "oauth",
    "access": "XXXXXX",
    "refresh": "XXXXXX",
    "expires": XXXXXX // Unix timestamp
  }
}

```

I have found the solution that works best for me, use https://github.com/router-for-me/CLIProxyAPI to serve models via a custom OpenAI endpoint and connect opencode to it as a custom OpenAI API provider.  If you don't have a homelabs server, best of luck 🙏✌️

This is my config:
```json
{
  "$schema": "https://opencode.ai/config.json",
  "autoupdate": true,
  "plugin": [
    "opencode-caffeinate",
    "opencode-notify"
  ],
  "provider": {
    "anthropic-selfhosted": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "Anthropic Self-Hosted",
      "options": {
        "baseURL":"**"
      },
      "models": {
        "claude-haiku-4-5-20251001": {
          "name": "Claude Haiku 4.5",
          "limit": {
            "context": 200000,
            "output": 65536
          }
        },
        "claude-opus-4-6": {
          "name": "Claude Opus 4.6",
          "limit": {
            "context": 200000,
            "output": 131072
          }
        },
        "claude-sonnet-4-6": {
          "name": "Claude Sonnet 4.6",
          "limit": {
            "context": 200000,
            "output": 65536
          }
        }
      }
    }
  }
}
```

